 "content": "def transform(grid):
    """Copy the horizontally repeated motif's extension into the other band."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out
    band_a, band_b = bands[0], bands[1]
    if len(band_a) != len(band_b):
        return out
    rows = len(band_a)
    cols_a = [c for r in band_a for c, v in enumerate(grid[r]) if v != bg]
    cols_b = [c for r in band_b for c, v in enumerate(grid[r]) if v != bg]
    if not cols_a or not cols_b:
        return out
    a0, a1 = min(cols_a), max(cols_a)
    b0, b1 = min(cols_b), max(cols_b)
    min_width = min(a1 - a0 + 1, b1 - b0 + 1)

    best = None
    for shift in range(-w + 1, w):
        lo = max(a0, b0 - shift)
        hi = min(a1, b1 - shift)
        overlap = hi - lo + 1
        if overlap < 0.70 * min_width:
            continue
        matches = 0
        total = rows * overlap
        for k in range(rows):
            ra, rb = band_a[k], band_b[k]
            for c in range(lo, hi + 1):
                matches += (grid[ra][c] != bg) == (grid[rb][c + shift] != bg)
        candidate = (matches / total, overlap, -abs(shift), shift)
        if best is None or candidate > best:
            best = candidate
    if best is None:
        return out
    shift = best[3]

    # For positive shift, A is the left copy and B the right copy. Transfer A's
    # overhang to B. For negative shift, transfer B's overhang to A. When the
    # best alignment is zero, copy the horizontally wider pattern into the other.
    if shift > 0:
        source_rows, target_rows, delta = band_a, band_b, shift
    elif shift < 0:
        source_rows, target_rows, delta = band_b, band_a, -shift
    elif a1 - a0 > b1 - b0:
        source_rows, target_rows, delta = band_a, band_b, 0
    elif b1 - b0 > a1 - a0:
        source_rows, target_rows, delta = band_b, band_a, 0
    else:
        return out

    for k in range(rows):
        sr, tr = source_rows[k], target_rows[k]
        for c in range(w):
            if grid[sr][c] != bg:
                tc = c + delta
                if 0 <= tc < w and grid[tr][tc] == bg:
                    out[tr][tc] = 1
    return out


