 "content": "from collections import Counter


def transform(grid):
    """Align the two separated motifs and copy the leading motif's overhang.

    Cells copied into the other motif are marked with color 1; matching existing
    foreground is left unchanged.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Locate the two non-background horizontal bands.
    occupied_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in occupied_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2 or len(bands[0]) != len(bands[1]):
        return out
    a, b = bands[:2]

    ca = [c for r in a for c, value in enumerate(grid[r]) if value != bg]
    cb = [c for r in b for c, value in enumerate(grid[r]) if value != bg]
    if not ca or not cb:
        return out
    a0, a1 = min(ca), max(ca)
    b0, b1 = min(cb), max(cb)
    min_width = min(a1 - a0 + 1, b1 - b0 + 1)

    # Find the horizontal offset: A[c] corresponds to B[c + shift].
    best = None
    for shift in range(-w + 1, w):
        lo = max(a0, b0 - shift)
        hi = min(a1, b1 - shift)
        overlap = hi - lo + 1
        if overlap < 0.70 * min_width:
            continue
        matches = 0
        total = len(a) * overlap
        for k, (ra, rb) in enumerate(zip(a, b)):
            for c in range(lo, hi + 1):
                matches += (grid[ra][c] != bg) == (grid[rb][c + shift] != bg)
        candidate = (matches / total, overlap, -abs(shift), shift)
        if best is None or candidate > best:
            best = candidate
    if best is None:
        return out

    shift = best[3]
    if shift > 0:
        # B is A shifted right; transfer A's overhang into B.
        src_rows, dst_rows, delta = a, b, shift
    elif shift < 0:
        # A is B shifted right; transfer B's overhang into A.
        src_rows, dst_rows, delta = b, a, -shift
    else:
        return out

    for sr, dr in zip(src_rows, dst_rows):
        for c, value in enumerate(grid[sr]):
            tc = c + delta
            if value != bg and 0 <= tc < w and grid[dr][tc] == bg:
                out[dr][tc] = 1
    return out


if __name__ == "__main__":
    pass
